function run(selected_text) {
  const normalized = selected_text.replace(/
?|
/g, "
");
  const hadTrailingNewline = normalized.endsWith("
");
  const lines = normalized.split("
");
  if (hadTrailingNewline) lines.pop();
  return lines.reverse().join("
") + (hadTrailingNewline ? "
" : "");
}
